+/****************************************************************************
+ * SPDX-License-Identifier: Apache-2.0
+ ****************************************************************************/
+
+#include <nuttx/config.h>
+
+#include <stdint.h>
+#include <syslog.h>
+
+#include <nuttx/clock.h>
+#include <nuttx/kthread.h>
+#include <nuttx/signal.h>
+
+#include "hardware/bk7258_mbox.h"
+
+#ifndef CONFIG_BK7258_LOG_PERF_TEST_COUNT
+#  define CONFIG_BK7258_LOG_PERF_TEST_COUNT 8
+#endif
+
+#ifndef CONFIG_BK7258_LOG_PERF_TEST_LENGTH
+#  define CONFIG_BK7258_LOG_PERF_TEST_LENGTH 96
+#endif
+
+#define BK7258_LOG_PERF_TEST_DELAY_MS 1000
+
+static int bk7258_log_perf_worker(int argc, char **argv)
+{
+  struct bk7258_mailbox_log_stats before;
+  struct bk7258_mailbox_log_stats after;
+  clock_t start;
+  clock_t elapsed;
+  unsigned int i;
+  char payload[CONFIG_BK7258_LOG_PERF_TEST_LENGTH];
+
+  (void)argc;
+  (void)argv;
+
+  for (i = 0; i < sizeof(payload) - 1; i++)
+    {
+      payload[i] = (char)('a' + (i % 26));
+    }
+
+  payload[sizeof(payload) - 1] = '\n';
+
+  /* Give the normal boot log and CP shell time to settle before measuring. */
+  nxsig_usleep(BK7258_LOG_PERF_TEST_DELAY_MS * 1000);
+  bk7258_mbox_get_log_stats(&before);
+  start = clock_systime_ticks();
+
+  for (i = 0; i < CONFIG_BK7258_LOG_PERF_TEST_COUNT; i++)
+    {
+      syslog(LOG_INFO, "[log-perf] seq=%u payload=%s", i, payload);
+    }
+
+  elapsed = clock_systime_ticks() - start;
+  bk7258_mbox_get_log_stats(&after);
+  syslog(LOG_WARNING,
+         "[log-perf] count=%u len=%u enqueue_ticks=%lu writes=%lu bytes=%lu queued=%u inflight=%u drop=%lu/%lu fifo=%lu ack_to=%lu tx_fail=%lu\n",
+         CONFIG_BK7258_LOG_PERF_TEST_COUNT,
+         (unsigned int)sizeof(payload),
+         (unsigned long)elapsed,
+         (unsigned long)(after.uart_write_calls - before.uart_write_calls),
+         (unsigned long)(after.uart_write_bytes - before.uart_write_bytes),
+         after.uart_queued,
+         after.uart_inflight,
+         (unsigned long)(after.uart_drop - before.uart_drop),
+         (unsigned long)(after.uart_drop_events - before.uart_drop_events),
+         (unsigned long)(after.fifo_full - before.fifo_full),
+         (unsigned long)(after.ack_timeout - before.ack_timeout),
+         (unsigned long)(after.uart_tx_fail - before.uart_tx_fail));
+
+  return 0;
+}
+
+int bk7258_log_perf_start(void)
+{
+  int pid;
+
+  pid = kthread_create("log-perf", 120, 2048,
+                       bk7258_log_perf_worker, NULL);
+  return pid < 0 ? pid : OK;
+}
